package com.campusmart.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="messages",indexes=@Index(name="idx_message_pair",columnList="sender_id,receiver_id")) public class Message {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private User sender;@ManyToOne(optional=false) private User receiver;@Column(nullable=false,length=2000) private String content;private LocalDateTime sentAt=LocalDateTime.now();public Long getId(){return id;}public User getSender(){return sender;}public void setSender(User v){sender=v;}public User getReceiver(){return receiver;}public void setReceiver(User v){receiver=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public LocalDateTime getSentAt(){return sentAt;}}
